// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address[] calldata tos, uint256[] calldata vs) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == vs.length);
        bool ok;
        bool ret;
        try c.transfer(from, from, tos, vs) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
        }
        // The reference contract, when it completes a transfer loop, reports success (true).
        assertTrue(!ok || ret);
    }
}
